        trace_llm_call(
            output_messages=[choice.message for choice in response.choices],  # type: ignore
            token_count_completion=completion_tokens,  # type: ignore
            token_count_prompt=prompt_tokens,  # type: ignore
            token_count_total=total_tokens,  # type: ignore
        )
        return LLMResponse(
            output=output,  # type: ignore
            prompt_token_count=prompt_tokens,  # type: ignore
            response_token_count=completion_tokens,  # type: ignore
        )


class AsyncManifestCallable(AsyncPromptCallableBase):
    async def invoke_llm(
        self,
        text: str,
        client: Any,
        instructions: Optional[str] = None,
        *args,
        **kwargs,
    ):
        """Async wrapper for manifest client.

        To use manifest for guardrails, do
        ```
        client = Manifest(client_name=..., client_connection=...)
        raw_llm_response, validated_response, *rest = guard(
            client,
            prompt_params={...},
            ...
        ```
        """
        try:
            import manifest  # noqa: F401 # type: ignore
        except ImportError:
            raise PromptCallableException(
                "The `manifest` package is not installed. "
                "Install with `poetry add manifest-ml`"
            )

        prompts = [nonchat_prompt(prompt=text, instructions=instructions)]

        trace_operation(
            input_mime_type="application/json",
            input_value={
                **kwargs,
                "prompts": prompts,
                "args": args,
            },
        )

        trace_llm_call(
            input_messages=chat_prompt(text, instructions),
            invocation_parameters={
                **kwargs,
                "prompts": prompts,
            },
        )

        client = cast(manifest.Manifest, client)
        manifest_response = await client.arun_batch(
            prompts=prompts,
            *args,
            **kwargs,
        )
        if kwargs.get("stream", False):
            raise NotImplementedError(
                "Manifest async streaming is not yet supported by manifest."
            )
        trace_operation(
            output_mime_type="application/json", output_value=manifest_response
        )
        trace_llm_call(
            output_messages=[{"role": "assistant", "content": manifest_response[0]}]
        )
        return LLMResponse(
            output=manifest_response[0],
        )


class AsyncArbitraryCallable(AsyncPromptCallableBase):
    def __init__(self, llm_api: Callable, *args, **kwargs):
        llm_api_args = inspect.getfullargspec(llm_api)
        if not llm_api_args.varkw:
            raise ValueError("Custom LLM callables must accept **kwargs!")
        if not llm_api_args.kwonlyargs or "messages" not in llm_api_args.kwonlyargs:
            warnings.warn(
                "We recommend including 'messages'"
                " as keyword-only arguments for custom LLM callables."
                " Doing so ensures these arguments are not unintentionally"
                " passed through to other calls via **kwargs.",
                UserWarning,
            )
        self.llm_api = llm_api
        super().__init__(*args, **kwargs)

    async def invoke_llm(self, *args, **kwargs) -> LLMResponse:
        """Wrapper for arbitrary callable.

        To use an arbitrary callable for guardrails, do
        ```
        raw_llm_response, validated_response, *rest = guard(
            my_callable,
            prompt_params={...},
            ...
        )
        ```
        """

        trace_operation(
            input_mime_type="application/json",
            input_value={
                **kwargs,
                "args": args,
            },
        )

        trace_llm_call(
            input_messages=chat_prompt(
                kwargs.get("prompt", ""), kwargs.get("instructions")
            ),
            invocation_parameters={
                **kwargs,
            },
        )

        output = await self.llm_api(*args, **kwargs)
        if kwargs.get("stream", False):
            # If stream is defined and set to True,
            # the callable returns a generator object
            return LLMResponse(
                output="",
                # FIXME: Why is this different from the synchronous streaming implementation?  ## noqa: E501
                # This shouldn't be necessary: https://docs.litellm.ai/docs/completion/stream#async-streaming
                async_stream_output=output.completion_stream,
            )

        trace_operation(output_mime_type="application/json", output_value=output)
        trace_llm_call(output_messages=[{"role": "assistant", "content": output}])

        return LLMResponse(
            output=output,
        )


def get_async_llm_ask(
    llm_api: Callable[..., Awaitable[Any]], *args, **kwargs
) -> AsyncPromptCallableBase:
    try:
        import litellm

        if llm_api == litellm.acompletion or (llm_api is None and kwargs.get("model")):
            return AsyncLiteLLMCallable(*args, **kwargs)
    except ImportError:
        pass

    try:
        import manifest  # noqa: F401 # type: ignore

        if isinstance(llm_api, manifest.Manifest):
            return AsyncManifestCallable(*args, client=llm_api, **kwargs)
    except ImportError:
        pass

    if llm_api is not None:
        return AsyncArbitraryCallable(*args, llm_api=llm_api, **kwargs)


def model_is_supported_server_side(
    llm_api: Optional[Union[Callable, Callable[..., Awaitable[Any]]]] = None,
    *args,
    **kwargs,
) -> bool:
    if not llm_api:
        return True
    # TODO: Support other models; requires server-side updates
    model = get_llm_ask(llm_api, *args, **kwargs)
    if asyncio.iscoroutinefunction(llm_api):
        model = get_async_llm_ask(llm_api, *args, **kwargs)
    return isinstance(model, LiteLLMCallable) or isinstance(model, AsyncLiteLLMCallable)


# CONTINUOUS FIXME: Update with newly supported LLMs
def get_llm_api_enum(
    llm_api: Callable[..., Awaitable[Any]], *args, **kwargs
) -> Optional[LLMResource]:
    # TODO: Distinguish between v1 and v2
    model = get_llm_ask(llm_api, *args, **kwargs)
    if isinstance(model, LiteLLMCallable):
        return LLMResource.LITELLM_DOT_COMPLETION
    elif isinstance(model, AsyncLiteLLMCallable):
        return LLMResource.LITELLM_DOT_ACOMPLETION

    else:
        return None

import logging
import logging.config
from logging import Handler, LogRecord
from typing import Dict, List, Optional

# from src.modules.otel_logger import handler as otel_handler

name = "guardrails-ai"
base_scope = "base"
all_scopes = "all"


class ScopeHandler(Handler):
    scope: str
    scoped_logs: Dict[str, List[LogRecord]]

    def __init__(self, level=logging.NOTSET, scope=base_scope):
        super().__init__(level)
        self.scope = scope
        self.scoped_logs = {}

    def emit(self, record: LogRecord) -> None:
        logs = self.scoped_logs.get(self.scope, [])
        logs.append(record)
        self.scoped_logs[self.scope] = logs

    def set_scope(self, scope: str = base_scope):
        self.scope = scope

    def get_all_logs(self) -> List[LogRecord]:
        all_logs = []
        for key in self.scoped_logs:
            logs = self.scoped_logs.get(key, [])
            all_logs.extend(logs)
        return all_logs

    def get_logs(self, scope: Optional[str] = None) -> List[LogRecord]:
        scope = scope or self.scope
        if scope == all_scopes:
            return self.get_all_logs()
        logs = self.scoped_logs.get(scope, [])
        return logs


class LoggerConfig:
    def __init__(self, config={}, level=logging.NOTSET, scope=base_scope):
        self.config = config
        self.level = level
        self.scope = scope


_logger = logging.getLogger(name)
handler = ScopeHandler()
scoped_logs: Dict[str, List[LogRecord]] = {}
logger_config = LoggerConfig()


def get_logger():
    _setup_handler(logger_config.level, logger_config.scope)

    if logger_config.config:
        logging.config.dictConfig(logger_config.config)

    _logger.setLevel(logger_config.level)

    get_scope_handler()

    return _logger


def set_config(config=None):
    if config is not None:
        logger_config.config = config
        logging.config.dictConfig(logger_config.config)


def set_level(level=None):
    if level is not None:
        logger_config.level = level
        _logger.setLevel(level)


def set_scope(scope: str = base_scope):
    logger_config.scope = scope
    scope_handler = get_scope_handler()
    scope_handler.set_scope(scope)


def _setup_handler(log_level=logging.NOTSET, scope=base_scope) -> ScopeHandler:
    global handler
    if not handler:
        handler = ScopeHandler(log_level, scope)
    return handler


def get_scope_handler() -> ScopeHandler:
    global _logger
    try:
        scope_handler: ScopeHandler = [
            h for h in _logger.handlers if isinstance(h, ScopeHandler)
        ][0]
        return scope_handler
    except IndexError:
        hdlr = _setup_handler()
        _logger.addHandler(hdlr)
        return hdlr


logger = get_logger()

"""Class for representing a prompt entry."""

import re
from string import Template
from typing import List, Optional

import regex

from guardrails.classes.templating.namespace_template import NamespaceTemplate
from guardrails.utils.constants import constants
from guardrails.utils.templating_utils import get_template_variables


class BasePrompt:
    """Base class for representing an LLM prompt."""

    def __init__(
        self,
        source: str,
        output_schema: Optional[str] = None,
        *,
        xml_output_schema: Optional[str] = None,
    ):
        """Initialize and substitute constants in the prompt."""
        self._source = source
        self.format_instructions_start = self.get_format_instructions_idx(source)

        # FIXME: Why is this happening on init instead of on format?
        # Substitute constants in the prompt.
        source = self.substitute_constants(source)

        # FIXME: Why is this happening on init instead of on format?
        # If an output schema is provided, substitute it in the prompt.
        if output_schema or xml_output_schema:
            self.source = Template(source).safe_substitute(
                output_schema=output_schema, xml_output_schema=xml_output_schema
            )
        else:
            self.source = source

    def __repr__(self) -> str:
        # Truncate the prompt to 50 characters and add ellipsis if it's longer.
        truncated_prompt = self.source[:50]
        if len(self.source) > 50:
            truncated_prompt += "..."
        return f"Prompt({truncated_prompt})"

    def __str__(self) -> str:
        return self.source

    @property
    def variable_names(self):
        return get_template_variables(self.source)

    @property
    def format_instructions(self):
        return self.source[self.format_instructions_start :]

    def substitute_constants(self, text: str) -> str:
        """Substitute constants in the prompt."""
        # Substitute constants by reading the constants file.
        # Regex to extract all occurrences of ${gr.<constant_name>}
        matches = re.findall(r"\${gr\.(\w+)}", text)

        # Substitute all occurrences of ${gr.<constant_name>}
        #   with the value of the constant.
        for match in matches:
            template = NamespaceTemplate(text)
            mapping = {f"gr.{match}": constants[match]}
            text = template.safe_substitute(**mapping)

        return text

    def get_prompt_variables(self) -> List[str]:
        return self.variable_names

    def format(self, **kwargs) -> "BasePrompt":
        raise NotImplementedError("Subclasses must implement this method.")

    def make_vars_optional(self):
        """Make all variables in the prompt optional."""
        for var in self.variable_names:
            self.source = self.source.replace(f"{{{var}}}", f"{{{var}:}}")

    def get_format_instructions_idx(self, text: str) -> Optional[int]:
        """Get the index of the first format instruction in the prompt.

        It checks to see where the first instance of any constant is in the text.
        Everything from then on is considered to be a format instruction.

        Returns:
            The index of the first format instruction in the prompt.
        """
        # TODO(shreya): Optionally add support for special character demarcation.

        # Regex to extract first occurrence of ${gr.<constant_name>}

        matches = re.finditer(r"\${gr\.(\w+)}", text)

        earliest_match_idx = None
        earliest_match = None

        # Find the earliest match where the match belongs to a constant.
        for match in matches:
            if match.group(1) in constants:
                if earliest_match_idx is None or earliest_match_idx > match.start():
                    earliest_match_idx = match.start()
                    earliest_match = match

        if earliest_match_idx is None:
            return 0

        if earliest_match is None:
            return None
        return earliest_match.start()

    def escape(self) -> str:
        """Escape single curly braces into double curly braces."""
        start_replaced = regex.sub(r"(?<!\$){", "{{", self.source)
        # This variable length negative lookbehind is why we need `regex` over `re`
        return regex.sub(r"(?<!\${.*)}", "}}", start_replaced)

    def _to_request(self) -> str:
        return self.source

"""Class for representing a messages entry."""

import re
from string import Template
from typing import Dict, List, Optional, Union

from guardrails.prompt import Prompt, Instructions
from guardrails.classes.templating.namespace_template import NamespaceTemplate
from guardrails.utils.constants import constants
from guardrails.utils.templating_utils import get_template_variables


class Messages:
    def __init__(
        self,
        source: List[Dict[str, Union[str, Prompt, Instructions]]],
        output_schema: Optional[str] = None,
        *,
        xml_output_schema: Optional[str] = None,
    ):
        self._source = source

        # FIXME: Why is this happening on init instead of on format?
        # Substitute constants in the prompt.
        for message in self._source:
            # if content is instance of Prompt class
            # call the substitute_constants method
            if isinstance(message["content"], str):
                message["content"] = self.substitute_constants(message["content"])

        # FIXME: Why is this happening on init instead of on format?
        # If an output schema is provided, substitute it in the prompt.
        if output_schema or xml_output_schema:
            for message in self._source:
                if isinstance(message["content"], str):
                    message["content"] = Template(message["content"]).safe_substitute(
                        output_schema=output_schema, xml_output_schema=xml_output_schema
                    )
        else:
            self.source = source

        # Ensure self.source is iterable
        self.source = list(self._source)
        self._index = 0

    def __iter__(self):
        self._index = 0
        return self

    def __next__(self):
        if self._index < len(self.source):
            result = self.source[self._index]
            self._index += 1
            return result
        else:
            raise StopIteration

    def format(
        self,
        **kwargs,
    ):
        """Format the messages using the given keyword arguments."""
        formatted_messages = []
        for message in self.source:
            if isinstance(message["content"], str):
                msg_str = message["content"]
            else:
                msg_str = message["content"]._source
            # Only use the keyword arguments that are present in the message.
            vars = get_template_variables(msg_str)
            filtered_kwargs = {k: v for k, v in kwargs.items() if k in vars}

            # Return another instance of the class with the formatted message.
            formatted_message = Template(msg_str).safe_substitute(**filtered_kwargs)
            formatted_messages.append(
                {"role": message["role"], "content": formatted_message}
            )
        return Messages(formatted_messages)

    def substitute_constants(self, text):
        """Substitute constants in the prompt."""
        # Substitute constants by reading the constants file.
        # Regex to extract all occurrences of ${gr.<constant_name>}
        matches = re.findall(r"\${gr\.(\w+)}", text)

        # Substitute all occurrences of ${gr.<constant_name>}
        #   with the value of the constant.
        for match in matches:
            template = NamespaceTemplate(text)
            mapping = {f"gr.{match}": constants[match]}
            text = template.safe_substitute(**mapping)

        return text

import copy
from string import Template
from typing import Dict, cast, Optional, Tuple

from guardrails.classes.output_type import OutputTypes
from guardrails.llm_providers import (
    LiteLLMCallable,
    AsyncLiteLLMCallable,
    PromptCallableBase,
)
from guardrails.prompt.prompt import Prompt
from guardrails.types.inputs import MessageHistory
from guardrails.prompt.instructions import Instructions


def messages_source(messages: MessageHistory) -> MessageHistory:
    messages_copy = []
    for msg in messages:
        msg_copy = copy.deepcopy(msg)
        content = (
            msg["content"].source
            if isinstance(msg["content"], Prompt)
            or isinstance(msg["content"], Instructions)
            else msg["content"]
        )
        msg_copy["content"] = content
        messages_copy.append(cast(Dict[str, str], msg_copy))
    return messages_copy


def preprocess_prompt_for_string_output(
    prompt_callable: PromptCallableBase,
    instructions: Optional[Instructions],
    prompt: Prompt,
) -> Tuple[Optional[Instructions], Prompt]:
    if isinstance(prompt_callable, LiteLLMCallable) or isinstance(
        prompt_callable, AsyncLiteLLMCallable
    ):
        prompt.source += "\n\nString Output:\n\n"
    if (
        isinstance(prompt_callable, LiteLLMCallable)
        or isinstance(prompt_callable, AsyncLiteLLMCallable)
    ) and not instructions:
        instructions = Instructions(
            "You are a helpful assistant, expressing yourself through a string."
        )

    return instructions, prompt


def preprocess_prompt_for_json_output(
    prompt_callable: PromptCallableBase,
    instructions: Optional[Instructions],
    prompt: Prompt,
    use_xml: bool,
) -> Tuple[Optional[Instructions], Prompt]:
    if isinstance(prompt_callable, LiteLLMCallable) or isinstance(
        prompt_callable, AsyncLiteLLMCallable
    ):
        prompt.source += "\n\nJson Output:\n\n"
    if (
        isinstance(prompt_callable, LiteLLMCallable)
        or isinstance(prompt_callable, AsyncLiteLLMCallable)
    ) and not instructions:
        schema_type = "XML schemas" if use_xml else "JSON schema"
        instructions = Instructions(
            Template(
                "You are a helpful assistant, "
                "able to express yourself purely through JSON, "
                "strictly and precisely adhering to the provided ${schema_type}."
            ).safe_substitute(schema_type=schema_type)
        )

    return instructions, prompt


def preprocess_prompt(
    prompt_callable: PromptCallableBase,
    instructions: Optional[Instructions],
    prompt: Prompt,
    output_type: OutputTypes,
    use_xml: bool,
) -> Tuple[Optional[Instructions], Prompt]:
    if output_type == OutputTypes.STRING:
        return preprocess_prompt_for_string_output(
            prompt_callable, instructions, prompt
        )
    return preprocess_prompt_for_json_output(
        prompt_callable, instructions, prompt, use_xml
    )

import jsonref
import re
import rstr
from builtins import max as get_max
from typing import Any, Dict, List, Optional, Union, cast
from pydash import upper_first, snake_case, camel_case, start_case, uniq_with, is_equal
from faker import Faker
from random import randint, randrange, uniform
from guardrails_api_client import SimpleTypes
from guardrails.utils.safe_get import safe_get

fake = Faker()


def get_decimal_places(num: Union[int, float]) -> int:
    return len(safe_get(str(num).split("."), 1, ""))


def closest_multiple(n, x):
    if x > n:
        return x
    z = (int)(x / 2)
    n = n + z
    n = n - (n % x)
    return n


def is_number(value: Any) -> bool:
    return str(value).replace(".", "").isnumeric()


def gen_sentence_case():
    words = " ".join(fake.words(2))
    return upper_first(words)


def gen_snake_case():
    words = " ".join(fake.words(2))
    return snake_case(words)


def gen_camel_case():
    words = " ".join(fake.words(2))
    return camel_case(words)


def gen_title_case():
    words = " ".join(fake.words(2))
    return start_case(words)


def gen_num(schema: Dict[str, Any]) -> Union[int, float]:
    schema_type = schema.get("type")
    minimum = schema.get("minimum")
    exclusive_minimum = schema.get("exclusiveMinimum")
    maximum = schema.get("maximum")
    exclusive_maximum = schema.get("exclusiveMaximum")
    multiple_of = schema.get("multipleOf")

    num_type = int if schema_type == SimpleTypes.INTEGER else float

    step = 1
    if multiple_of and is_number(multiple_of):
        step = multiple_of
    elif schema_type != SimpleTypes.INTEGER:
        specified_min = minimum or exclusive_minimum or 0
        specified_max = maximum or exclusive_maximum or 100
        min_digits = get_decimal_places(specified_min)
        max_digits = get_decimal_places(specified_max)
        highest_precision = get_max(min_digits, max_digits)
        step = float(f"{0:.{highest_precision - 1}f}1") if highest_precision else 1

    min = 0
    max = 100
    if minimum and str(minimum).isnumeric():
        min = minimum
    elif exclusive_minimum and is_number(exclusive_minimum):
        min = num_type(exclusive_minimum) + step

    if maximum and is_number(maximum):
        max = maximum
    elif exclusive_maximum and is_number(exclusive_maximum):
        max = num_type(exclusive_maximum) - step

    random_num = 0
    if schema_type == SimpleTypes.INTEGER or isinstance(step, int):
        random_num = num_type(randrange(min, max, step))  # type: ignore
    else:
        precision = get_decimal_places(step)
        random_num = round(num_type(uniform(min, max)), precision)
        random_num = round(closest_multiple(random_num, step), precision)

    return random_num


def gen_formatted_string(format: str, default: str) -> str:
    value = default
    if format == "date":
        value = fake.date("YYYY-MM-DD")
    elif format == "date-time":
        value = fake.date_time_this_century().isoformat("T")
    elif format == "time":
        value = fake.time()
    elif format == "percentage":
        value = f"{round(uniform(0, 100), 2)}%"
    elif format == "email":
        value = fake.email()
    elif format == "url" or format == "uri":
        value = fake.url()
    elif format == "snake_case":
        value = gen_snake_case()
    elif format == "regex":
        value = ".*"
    elif format == "camelCase":
        value = gen_camel_case()
    elif format == "Title Case":
        value = gen_title_case()
    elif hasattr(fake, format) and callable(getattr(fake, format)):
        gen_func = getattr(fake, format)
        value = gen_func()

    return value


def gen_string(schema: Dict[str, Any], *, property_name: Optional[str] = None) -> str:
    # Look at format first, then pattern; not xor
    gen_func = fake.word
    # Lazy attempt to choose a relevant faker function
    if (
        property_name
        and hasattr(fake, property_name)
        and callable(getattr(fake, property_name))
    ):
        gen_func = getattr(fake, property_name)

    value = gen_func()

    schema_format = schema.get("format")
    if schema_format:
        value = gen_formatted_string(schema_format, value)

    schema_pattern = schema.get("pattern")
    regex_pattern = re.compile(schema_pattern) if schema_pattern else None  # type: ignore
    if schema_pattern and regex_pattern and not regex_pattern.search(value):
        value = rstr.xeger(schema_pattern)

    return value


def gen_array(
    schema: Dict[str, Any], *, property_name: Optional[str] = None
) -> List[Any]:
    """
    What we do support:
        - items
        - minItems
        - maxItem
        - uniqueItems
    What we do NOT support:
        - prefixItems
        - unevaluatedItems
        - contains
    """
    item_schema = schema.get("items", {})
    min_items = schema.get("minItems", 1)
    max_item = schema.get("maxItem", 2)
    unique_items = schema.get("uniqueItems", False)

    gen_amount = randint(min_items, max_item)

    array_items = []
    while len(array_items) < gen_amount:
        item = _generate_example(item_schema, property_name=property_name)
        array_items.append(item)
        if unique_items:
            array_items = uniq_with(array_items, is_equal)

    return array_items


def gen_object(schema: Dict[str, Any]) -> Dict[str, Any]:
    """
    What we do support:
        - properties
        - schema compositions: Addressed in _generate_example
            - oneOf
            - anyOf
            - allOf
        - conditional sub-schemas: Addressed in _generate_example
            - if/then/else
            - allOf[if/then/else]

    What we do NOT support:
            - patternProperties
            - additionalProperties
            - unevaluatedProperties
            - propertyNames
            - minProperties
            - maxProperties
            - dependentSchemas (just use anyOf)
            - dependentRequired (we generate all properties; so this is validation only)
    """
    value = {}
    properties: Dict[str, Any] = schema.get("properties", {})
    for k, v in properties.items():
        value[k] = _generate_example(v, property_name=k)

    return value


def gen_from_type(
    schema: Dict[str, Any], *, property_name: Optional[str] = None
) -> Any:
    schema_type = schema.get("type")
    if schema_type == SimpleTypes.ARRAY:
        return gen_array(schema, property_name=property_name)
    elif schema_type == SimpleTypes.BOOLEAN:
        return fake.boolean()
    elif schema_type == SimpleTypes.INTEGER:
        return gen_num(schema)
    elif schema_type == SimpleTypes.NULL:
        return None
    elif schema_type == SimpleTypes.NUMBER:
        return gen_num(schema)
    elif schema_type == SimpleTypes.OBJECT:
        return gen_object(schema)
    elif schema_type == SimpleTypes.STRING:
        return gen_string(schema, property_name=property_name)


def gen_from_enum(enum: List[Any]) -> Any:
    random_enum_index = randint(0, len(enum) - 1)
    return safe_get(enum, random_enum_index)


def evaluate_if_block(schema: Dict[str, Any], value: Any) -> Any:
    if_block: Dict[str, Any] = schema.get("if", {})
    if_properties: Dict[str, Any] = if_block.get("properties", {})

    then_block: Dict[str, Any] = schema.get("then", {})
    then_properties: Dict[str, Any] = then_block.get("properties", {})

    else_block: Dict[str, Any] = schema.get("else", {})
    else_properties: Dict[str, Any] = else_block.get("properties", {})

    sub_schema = else_properties

    condition_satisfied = True
    for k, v in if_properties.items():
        actual_value = safe_get(value, k)
        condition_value = safe_get(v, "const")
        condition_satisfied = condition_satisfied and actual_value == condition_value

    if condition_satisfied:
        sub_schema = then_properties

    for k, v in sub_schema.items():
        sub_schema_value = _generate_example(v, property_name=k)
        value[k] = sub_schema_value

    return value


def pick_sub_schema(
    schema: Dict[str, Any], sub_schema_key: str, *, property_name: Optional[str] = None
) -> Any:
    sub_schema: List[Dict[str, Any]] = schema.pop(sub_schema_key, [])
    # Pick a sub-schema
    random_index = randint(0, len(sub_schema) - 1)
    chosen_sub_schema = safe_get(sub_schema, random_index, {})

    # Factor
    factored_schema = {**schema, **chosen_sub_schema}
    return _generate_example(factored_schema, property_name=property_name)


def evaluate_all_of(
    schema: Dict[str, Any], value: Any, *, property_name: Optional[str] = None
) -> Any:
    # If 'type' isn't specified but 'allOf' is applied;
    #   it is safe to assume the schema is of type 'object'
    all_of: List[Dict[str, Any]] = schema.pop("allOf", [])
    schema_type = schema.get("type", SimpleTypes.OBJECT)
    if schema_type == SimpleTypes.OBJECT:
        # Check for "if" blocks, group by properties, pick one of each group
        # "if" blocks can _only_ be applied to objects
        if_blocks = [sub for sub in all_of if sub.get("if")]
        for if_block in if_blocks:
            factored_schema = {**schema, **if_block}
            value = evaluate_if_block(factored_schema, value)

        other_blocks = [sub for sub in all_of if not sub.get("if")]
        for sub_schema in other_blocks:
            sub_schema_value = _generate_example(
                sub_schema, property_name=property_name
            )
            value = {**value, **sub_schema_value}
        return value
    else:
        compressed_schema = {**schema}
        for sub_schema in all_of:
            compressed_schema.update(sub_schema)
        return _generate_example(compressed_schema, property_name=property_name)


def _generate_example(
    json_schema: Dict[str, Any], *, property_name: Optional[str] = None
) -> Any:
    # Apply base schema
    schema_type = json_schema.get("type")
    const = json_schema.get("const")
    enum = json_schema.get("enum")

    value = None
    if const:
        value = const
    elif enum:
        value = gen_from_enum(enum)
    elif schema_type:
        value = gen_from_type(json_schema, property_name=property_name)

    # Apply Conditional Schema
    if_block: Dict[str, Any] = json_schema.get("if", {})
    if if_block:
        value = evaluate_if_block(json_schema, value)
    # elif discriminator:
    #     # Don't need to evaluate this;
    #     # It is implied in the oneOf
    #     pass

    # Apply Schema Compositions
    one_of: List[Dict[str, Any]] = json_schema.get("oneOf", [])
    any_of: List[Dict[str, Any]] = json_schema.get("anyOf", [])
    all_of: List[Dict[str, Any]] = json_schema.get("allOf", [])
    if one_of:
        value = pick_sub_schema(json_schema, "oneOf")
    elif any_of:
        value = pick_sub_schema(json_schema, "anyOf")
    elif all_of:
        value = evaluate_all_of(json_schema, value, property_name=property_name)

    return value


def generate_example(
    json_schema: Dict[str, Any], *, property_name: Optional[str] = None
) -> Any:
    """Takes a json schema and generates a sample object."""
    dereferenced_schema = cast(Dict[str, Any], jsonref.replace_refs(json_schema))
    return _generate_example(dereferenced_schema, property_name=property_name)

from typing import (
    Any,
    Callable,
    Dict,
    List,
    Optional,
    Tuple,
    Type,
    Union,
    get_args,
    get_origin,
)

from pydantic import AliasChoices, AliasGenerator, AliasPath, BaseModel
from pydantic.fields import FieldInfo
from guardrails.classes.output_type import OutputTypes
from guardrails.classes.schema.processed_schema import ProcessedSchema
from guardrails.classes.validation.validator_reference import ValidatorReference
from guardrails.logger import logger
from guardrails.types import (
    ModelOrListOfModels,
    ModelOrListOrDict,
    ModelOrModelUnion,
)
from guardrails.utils.safe_get import safe_get
from guardrails.utils.validator_utils import safe_get_validator
from guardrails.validator_base import Validator


def _resolve_alias(alias: Union[str, AliasPath, AliasChoices]) -> List[str]:
    aliases = []
    if isinstance(alias, str):
        aliases.append(alias)
    elif isinstance(alias, AliasPath):
        aliases.append(".".join(str(alias.path)))
    elif isinstance(alias, AliasChoices):
        for choice in alias.choices:
            aliases.extend(_resolve_alias(choice))

    return aliases


def _collect_aliases(
    field: Union[FieldInfo, AliasGenerator], field_name: str, model: Type[BaseModel]
) -> List[str]:
    aliases = []

    if field.alias:
        if isinstance(field.alias, str):
            aliases.append(field.alias)
        elif isinstance(field.alias, Callable):
            aliases.append(field.alias(field_name))

    if field.serialization_alias:
        if isinstance(field.serialization_alias, str):
            aliases.append(field.serialization_alias)
        elif isinstance(field.serialization_alias, Callable):
            aliases.append(field.serialization_alias(field_name))

    if field.validation_alias:
        if isinstance(field.validation_alias, Callable):
            aliases.extend(_resolve_alias(field.validation_alias(field_name)))
        else:
            aliases.extend(_resolve_alias(field.validation_alias))

    alias_generator = model.model_config.get("alias_generator")
    if alias_generator:
        if isinstance(alias_generator, Callable):
            aliases.append(alias_generator(field_name))
        elif isinstance(alias_generator, AliasGenerator):
            return _collect_aliases(alias_generator, field_name, model)

    return aliases


def is_base_model_type(any_type: Any) -> bool:
    try:
        inherits_from_base_model = issubclass(any_type, BaseModel)
        return inherits_from_base_model
    except TypeError:
        return False


def get_base_model(
    pydantic_class: ModelOrListOrDict,
) -> Tuple[ModelOrModelUnion, Any, Optional[Any]]:
    schema_model = pydantic_class
    type_origin = get_origin(pydantic_class)
    key_type_origin = None

    if type_origin is list:
        item_types = get_args(pydantic_class)
        if len(item_types) > 1:
            raise ValueError("List data type must have exactly one child.")
        item_type = safe_get(item_types, 0)
        if not item_type or not issubclass(item_type, BaseModel):
            raise ValueError("List item type must be a Pydantic model.")
        schema_model = item_type
    elif type_origin is dict:
        key_value_types = get_args(pydantic_class)
        value_type = safe_get(key_value_types, 1)
        key_type_origin = safe_get(key_value_types, 0)
        if not value_type or not issubclass(value_type, BaseModel):
            raise ValueError("Dict value type must be a Pydantic model.")
        schema_model = value_type
    elif type_origin is Union:
        union_members = get_args(pydantic_class)
        model_members = list(filter(is_base_model_type, union_members))
        if len(model_members) > 0:
            schema_model = Union[tuple(union_members)]  # type: ignore
            return (schema_model, type_origin, key_type_origin)

    if not is_base_model_type(schema_model):
        raise ValueError(
            "'output_class' must be of Type[pydantic.BaseModel]"
            " or List[Type[pydantic.BaseModel]]!"
        )

    return (schema_model, type_origin, key_type_origin)


def try_get_base_model(
    pydantic_class: ModelOrListOrDict,
) -> Tuple[Optional[Type[BaseModel]], Optional[Any], Optional[Any]]:
    try:
        model, type_origin, key_type_origin = get_base_model(pydantic_class)
        return (model, type_origin, key_type_origin)
    except ValueError:
        return (None, None, None)
    except TypeError:
        return (None, None, None)


def extract_union_member(
    member: Type,
    processed_schema: ProcessedSchema,
    json_path: str,
    aliases: List[str],
) -> Type:
    aliases = aliases or []
    field_model, field_type_origin, key_type_origin = try_get_base_model(member)
    if not field_model:
        return member
    if field_type_origin is Union:
        union_members = get_args(field_model)
        extracted_union_members = []
        for m in union_members:
            extracted_union_members.append(
                extract_union_member(m, processed_schema, json_path, aliases)
            )
        return Union[tuple(extracted_union_members)]  # type: ignore

    else:
        extracted_field_model = extract_validators(
            model=field_model,
            processed_schema=processed_schema,
            json_path=json_path,
            aliases=aliases,
        )
        if field_type_origin is list:
            return List[extracted_field_model]
        elif field_type_origin is dict:
            return Dict[key_type_origin, extracted_field_model]  # type: ignore
        return extracted_field_model


def extract_validators(
    model: Type[BaseModel],
    processed_schema: ProcessedSchema,
    json_path: str,
    aliases: Optional[List[str]] = None,
) -> Type[BaseModel]:
    aliases = aliases or []
    for field_name in model.model_fields:
        alias_paths = []
        field_path = f"{json_path}.{field_name}"
        # alias_paths.append(field_path)
        for alias_path in aliases:
            alias_paths.append(f"{alias_path}.{field_name}")
        field: FieldInfo = model.model_fields[field_name]
        for alias in _collect_aliases(field, field_name, model):
            alias_paths.append(f"{json_path}.{alias}")
            for alias_path in aliases:
                alias_paths.append(f"{alias_path}.{alias}")

        if field.json_schema_extra is not None and isinstance(
            field.json_schema_extra, dict
        ):
            # NOTE: It's impossible to copy a class type so using
            #   'pop' here mutates the original Pydantic Model.
            # Using 'get' adds a pointless 'validators' field to the
            #   json schema but that doesn't break anything.
            validators = field.json_schema_extra.get("validators", [])

            if not isinstance(validators, list) and not isinstance(
                validators, Validator
            ):
                logger.warning(
                    f"Invalid value assigned to {field_name}.validators! {validators}"
                )
                continue
            validator_instances: List[Validator] = []

            # Only for backwards compatibility
            if isinstance(validators, Validator):
                validator_instances.append(validators)
            else:
                validator_list = [
                    safe_get_validator(v)  # type: ignore
                    for v in validators
                ]
                validator_instances.extend([v for v in validator_list if v is not None])
            all_paths = [field_path]
            all_paths.extend(alias_paths)
            for path in all_paths:
                entry = processed_schema.validator_map.get(path, [])
                entry.extend(validator_instances)
                processed_schema.validator_map[path] = entry
                validator_references = [
                    ValidatorReference(
                        id=v.rail_alias,
                        on=path,
                        on_fail=v.on_fail_descriptor,  # type: ignore
                        kwargs=v.get_args(),
                    )
                    for v in validator_instances
                ]
                processed_schema.validators.extend(validator_references)
        if field.annotation:
            field_model, field_type_origin, key_type_origin = try_get_base_model(
                field.annotation
            )
            if field_model:
                if field_type_origin is Union:
                    union_members = list(get_args(field_model))
                    extracted_union_members = []
                    for m in union_members:
                        extracted_union_members.append(
                            extract_union_member(
                                m,
                                processed_schema=processed_schema,
                                json_path=field_path,
                                aliases=alias_paths,
                            )
                        )

                    model.model_fields[field_name].annotation = Union[  # type: ignore
                        tuple(extracted_union_members)  # type: ignore
                    ]
                else:
                    extracted_field_model = extract_validators(
                        model=field_model,
                        processed_schema=processed_schema,
                        json_path=field_path,
                        aliases=alias_paths,
                    )
                    if field_type_origin is list:
                        model.model_fields[field_name].annotation = List[
                            extracted_field_model
                        ]
                    elif field_type_origin is dict:
                        model.model_fields[field_name].annotation = Dict[
                            key_type_origin, extracted_field_model  # type: ignore
                        ]
                    else:
                        model.model_fields[
                            field_name
                        ].annotation = extracted_field_model  # noqa
    return model


def pydantic_to_json_schema(
    pydantic_class: Type[BaseModel], type_origin: Optional[Any] = None
) -> Dict[str, Any]:
    # Convert Pydantic model to JSON schema
    json_schema = pydantic_class.model_json_schema()
    json_schema["title"] = pydantic_class.__name__

    if type_origin is list:
        json_schema = {
            "title": f"Array<{json_schema.get('title')}>",
            "type": "array",
            "items": json_schema,
        }

    return json_schema


def pydantic_model_to_schema(
    pydantic_class: ModelOrListOfModels,
) -> ProcessedSchema:
    processed_schema = ProcessedSchema(validators=[], validator_map={})

    schema_model, type_origin, _key_type_origin = get_base_model(pydantic_class)

    processed_schema.output_type = (
        OutputTypes.LIST if type_origin is list else OutputTypes.DICT
    )

    model = extract_validators(schema_model, processed_schema, "$")
    json_schema = pydantic_to_json_schema(model, type_origin)
    processed_schema.json_schema = json_schema

    return processed_schema

import json
from typing import Any, Dict, List, Optional
from jsonschema import Draft202012Validator, ValidationError
from referencing import Registry, jsonschema as jsonschema_ref

from guardrails.actions.reask import SkeletonReAsk
from guardrails.classes.validation.validation_result import FailResult


class SchemaValidationError(Exception):
    fields: Dict[str, List[str]] = {}

    def __init__(self, *args: object, fields: Dict[str, List[str]]):
        self.fields = fields
        super().__init__(*args)


def validate_against_schema(
    payload: Any,
    validator: Draft202012Validator,
    *,
    validate_subschema: Optional[bool] = False,
):
    fields: Dict[str, List[str]] = {}
    error: ValidationError
    for error in validator.iter_errors(payload):
        if validate_subschema is True and error.message.endswith(
            "is a required property"
        ):
            continue
        fields[error.json_path] = fields.get(error.json_path, [])
        fields[error.json_path].append(error.message)

    if fields:
        error_message = (
            "The provided payload is not compliant with the provided schema!"
        )
        raise SchemaValidationError(error_message, fields=fields)


def validate_json_schema(json_schema: Dict[str, Any]):
    """Validates a json_schema, against the JSON Meta Schema Draft 2020-12.

    Raises a SchemaValidationError if invalid.
    """
    json_schema_validator = Draft202012Validator(
        {
            "$ref": "https://json-schema.org/draft/2020-12/schema",
        }
    )
    try:
        validate_against_schema(json_schema, json_schema_validator)
    except SchemaValidationError as e:
        schema_name = json_schema.get("title", json_schema.get("$id"))
        error_message = (
            f"Schema {schema_name} is not compliant with JSON Schema Draft 2020-12!"
        )
        raise SchemaValidationError(error_message, fields=e.fields)


def validate_payload(
    payload: Any,
    json_schema: Dict[str, Any],
    *,
    validate_subschema: Optional[bool] = False,
):
    """Validates a payload, against the provided JSON Schema.

    Raises a SchemaValidationError if invalid.
    """
    schema_id = json_schema.get("$id", "temp-schema")
    registry = Registry().with_resources(
        [
            (
                f"urn:{schema_id}",
                jsonschema_ref.DRAFT202012.create_resource(json_schema),
            )
        ]
    )
    validator = Draft202012Validator(
        {
            "$ref": f"urn:{schema_id}",
        },
        registry=registry,
        # TODO: Add custom checks for date: format,
        #   time: format, date-time: format, etc.
        # format_checker=draft202012_format_checker
    )
    validate_against_schema(payload, validator, validate_subschema=validate_subschema)


def schema_validation(llm_output: Any, output_schema: Dict[str, Any], **kwargs):
    validate_subschema = kwargs.get("validate_subschema", False)

    schema_error = None
    try:
        validate_payload(
            llm_output, output_schema, validate_subschema=validate_subschema
        )
    except SchemaValidationError as sve:
        formatted_error_fields = json.dumps(sve.fields, indent=2)
        schema_error = f"JSON does not match schema:\n{formatted_error_fields}"

    if schema_error:
        return SkeletonReAsk(
            incorrect_value=llm_output,
            fail_results=[
                FailResult(
                    fix_value=None,
                    error_message=schema_error,
                )
            ],
        )

import threading
from typing import Optional

from guardrails.classes.rc import RC


class Settings:
    _instance = None
    _lock = threading.Lock()
    _rc: RC
    _watch_mode_enabled: bool
    """Whether to use a local server for running Guardrails."""
    use_server: Optional[bool]
    """Whether to disable tracing.

    Traces are only ever sent to a telemetry sink you specify via
    environment variables or by instantiating a TracerProvider.
    """
    disable_tracing: Optional[bool]

    def __new__(cls) -> "Settings":
        if cls._instance is None:
            with cls._lock:
                if cls._instance is None:
                    cls._instance = super(Settings, cls).__new__(cls)
                    cls._instance._initialize()
        return cls._instance

    def _initialize(self):
        self.use_server = None
        self.disable_tracing = None
        self._rc = RC.load()
        self._watch_mode_enabled = False

    @property
    def rc(self) -> RC:
        if self._rc is None:
            self._rc = RC.load()
        return self._rc

    @rc.setter
    def rc(self, value: RC):
        self._rc = value

    @property
    def watch_mode_enabled(self) -> bool:
        return self._watch_mode_enabled


settings = Settings()

from contextvars import ContextVar, copy_context
from typing import Any, Dict, Literal, Union


GUARD_NAME_KEY: Literal["gr.reserved.guard.name"] = "gr.reserved.guard.name"
DOCUMENT_STORE_KEY: Literal["gr.reserved.document_store"] = "gr.reserved.document_store"
CALL_KWARGS_KEY: Literal["gr.reserved.call_kwargs"] = "gr.reserved.call_kwargs"


def set_guard_name(guard_name: str) -> None:
    set_context_var(GUARD_NAME_KEY, guard_name)


def get_guard_name() -> str:
    return get_context_var(GUARD_NAME_KEY) or ""


def set_call_kwargs(kwargs: Dict[str, Any]) -> None:
    set_context_var(CALL_KWARGS_KEY, kwargs)


def get_call_kwargs() -> Dict[str, Any]:
    return get_context_var(CALL_KWARGS_KEY) or {}


def get_call_kwarg(kwarg_key: str) -> Union[Any, None]:
    kwargs = get_call_kwargs()
    return kwargs.get(kwarg_key)


def _get_contextvar(key):
    context = copy_context()
    context_var = None
    for c_key in context.keys():
        if c_key.name == key:
            context_var = c_key
            break
    return context_var


def set_context_var(key, value):
    context_var = _get_contextvar(key) or ContextVar(key)
    context_var.set(value)


def get_context_var(key):
    context_var = _get_contextvar(key)
    return context_var.get() if context_var else None

import json
from typing import Any, Callable, Dict, Optional, Union, List
from opentelemetry.baggage import get_baggage
from opentelemetry import context
from opentelemetry.context import Context
from opentelemetry.trace import Span

from guardrails.logger import logger


def get_current_context() -> Union[Context, None]:
    otel_current_context = (
        context.get_current()
        if context is not None and hasattr(context, "get_current")
        else None
    )
    return otel_current_context


def get_span(span: Optional[Span] = None) -> Optional[Span]:
    if span is not None and hasattr(span, "add_event"):
        return span
    try:
        from opentelemetry import trace

        current_context = get_current_context()
        current_span = trace.get_current_span(current_context)
        return current_span
    except Exception as e:
        logger.error(e)
        return None


def serialize(val: Any) -> Optional[str]:
    try:
        if val is None:
            return None
        if hasattr(val, "to_dict"):
            return json.dumps(val.to_dict())
        elif hasattr(val, "__dict__"):
            return json.dumps(val.__dict__)
        elif isinstance(val, dict) or isinstance(val, list):
            return json.dumps(val)
        return str(val)
    except Exception:
        return None


def to_dict(val: Any) -> Dict:
    try:
        if val is None:
            return {}
        elif isinstance(val, dict):
            return val
        elif hasattr(val, "to_dict"):
            return val.to_dict()
        elif hasattr(val, "__dict__"):
            return val.__dict__
        else:
            return dict(val)
    except Exception:
        return {}


def wrap_with_otel_context(
    outer_scope_otel_context: Context, func: Callable[..., Any]
) -> Callable[..., Any]:
    """This function is designed to ensure that a given OpenTelemetry context
    is applied when executing a specified function. It is particularly useful
    for preserving the trace context when a guardrails is executed in a
    different execution flow or when integrating with other frameworks.

    Args:
        outer_scope_otel_context (Context): The OpenTelemetry context to apply
            when executing the function.
        func (Callable[..., Any]): The function to be executed within
            the given OpenTelemetry context.

    Returns:
        Callable[..., Any]: A wrapped version of 'func' that, when called,
            executes with 'outer_scope_otel_context' applied.
    """

    def wrapped_func(*args: Any, **kwargs: Any) -> Any:
        # Attach the specified OpenTelemetry context before executing 'func'
        token = context.attach(outer_scope_otel_context)
        try:
            # Execute 'func' within the attached context
            return func(*args, **kwargs)
        finally:
            # Ensure the context is detached after execution
            #   to maintain correct context management
            context.detach(token)

    return wrapped_func


def add_user_attributes(span: Span):
    try:
        client_ip = get_baggage("client.ip") or "unknown"
        user_agent = get_baggage("http.user_agent") or "unknown"
        referrer = get_baggage("http.referrer") or "unknown"
        user_id = get_baggage("user.id") or "unknown"
        organization = get_baggage("organization") or "unknown"
        app = get_baggage("app") or "unknown"

        span.set_attribute("client.ip", str(client_ip))
        span.set_attribute("http.user_agent", str(user_agent))
        span.set_attribute("http.referrer", str(referrer))
        span.set_attribute("user.id", str(user_id))
        span.set_attribute("organization", str(organization))
        span.set_attribute("app", str(app))
    except Exception as e:
        logger.warning("Error loading baggage user information", e)
        pass


def redact(value: str) -> str:
    """Redacts all but the last four characters of the given string.

    Args:
        value (str): The string to be redacted.

    Returns:
        str: The redacted string with all but the last four characters
              replaced by asterisks.
    """
    redaction_length = len(value) - 4
    stars = "*" * redaction_length
    return f"{stars}{value[-4:]}"


def ismatchingkey(
    target_key: str,
    keys_to_match: tuple[str, ...] = ("key", "token", "password"),
) -> bool:
    """Check if the target key contains any of the specified keys to match.

    Args:
        target_key (str): The key to be checked.
        keys_to_match (tuple[str, ...], optional): A tuple of keys to match
                against the target key. Defaults to ("key", "token").

    Returns:
        bool: True if any of the keys to match are found in the target key,
              False otherwise.
    """
    for k in keys_to_match:
        if k in target_key:
            return True
    return False


def can_convert_to_dict(s: str) -> bool:
    """Check if a string can be converted to a dictionary.

    This function attempts to load the input string as JSON. If successful,
    it returns True, indicating that the string can be converted to a dictionary.
    Otherwise, it catches ValueError and TypeError exceptions and returns False.

    Args:
        s (str): The input string to be checked.

    Returns:
        bool: True if the string can be converted to a dictionary, False otherwise.
    """
    try:
        json.loads(s)
        return True
    except (ValueError, TypeError):
        return False


def recursive_key_operation(
    data: Optional[Union[Dict[str, Any], List[Any], str]],
    operation: Callable[[str], str],
    keys_to_match: List[str] = ["key", "token", "password"],
) -> Optional[Union[Dict[str, Any], List[Any], str]]:
    """Recursively traverses a dictionary, list, or JSON string and applies a
    specified operation to the values of keys that match any in the
    `keys_to_match` list. This function is useful for masking sensitive data
    (e.g., keys, tokens, passwords) in nested structures.

    Args:
        data (Optional[Union[Dict[str, Any], List[Any], str]]): The input data
            to traverse. This can bea dictionary, list, or JSON string. If a
            JSON string is provided, it will be parsed into a dictionary before
            processing.

        operation (Callable[[str], str]): A function that takes a string value
            and returns a modified string. This operation is applied to the values
            of keys that match any in `keys_to_match`.
        keys_to_match (List[str]): A list of keys to search for in the data. If
            a key matche any in this list, the corresponding value will be processed
            by the `operation`. Defaults to ["key", "token", "password"].

    Returns:
        Optional[Union[Dict[str, Any], List[Any], str]]: The modified data structure
        with the operation applied to the values of matched keys. The return type
        matches the input type (dict, list, or str).
    """
    if isinstance(data, str) and can_convert_to_dict(data):
        data_dict = json.loads(data)
        data = str(recursive_key_operation(data_dict, operation, keys_to_match))
    elif isinstance(data, dict):
        for key, value in data.items():
            if ismatchingkey(key, tuple(keys_to_match)) and isinstance(value, str):
                # Apply the operation to the value of the matched key
                data[key] = operation(value)
            else:
                # Recursively process nested dictionaries or lists
                data[key] = recursive_key_operation(value, operation, keys_to_match)
    elif isinstance(data, list):
        for i in range(len(data)):
            data[i] = recursive_key_operation(data[i], operation, keys_to_match)

    return data

