def messages_to_prompt_string(
    messages: t.Union[
        list[dict[str, t.Union[str, Prompt, Instructions]]], MessageHistory
    ],
) -> str:
    messages_copy = ""
    for msg in messages:
        content = (
            msg["content"].source  # type: ignore
