from typing import Literal, get_args

ON_FAIL_TYPES = Literal[
    "exception", "fix", "fix_reask", "reask", "filter", "refrain", "noop", "custom"
]


def on_fail(fix_type: ON_FAIL_TYPES = "noop"):
    options = get_args(ON_FAIL_TYPES)
    assert fix_type in options, f"'{fix_type}' is not in {options}"
    return {"on_fail": fix_type}

import os
from typing import Any, Dict, Iterator, List, Optional, cast

import openai

from guardrails.classes.llm.llm_response import LLMResponse
from guardrails.utils.safe_get import safe_get
from guardrails.telemetry import trace_llm_call, trace_operation


class OpenAIClientV1:
    def __init__(
        self,
        api_key: Optional[str] = None,
        api_base: Optional[str] = None,
        *args,
        **kwargs,
    ):
        if api_key is None:
            api_key = os.environ.get("OPENAI_API_KEY")
        self.api_key = api_key
        self.api_base = api_base
        self.client = openai.Client(
            api_key=self.api_key,
            base_url=self.api_base,
        )

    def create_embedding(
        self,
        model: str,
        input: List[str],
    ) -> List[List[float]]:
        embeddings = self.client.embeddings.create(
            model=model,
            input=input,
        )
        return [r.embedding for r in embeddings.data]

    def create_completion(
        self, engine: str, prompt: str, *args, **kwargs
    ) -> LLMResponse:
        trace_operation(
            input_mime_type="application/json",
            input_value={
                **kwargs,
                "model": engine,
                "prompt": prompt,
                "args": args,
            },
        )

        trace_llm_call(
            invocation_parameters={
                **kwargs,
                "model": engine,
                "prompt": prompt,
            }
        )

        response = self.client.completions.create(
            model=engine, prompt=prompt, *args, **kwargs
        )

        trace_operation(output_mime_type="application/json", output_value=response)

        return self.construct_nonchat_response(
            stream=kwargs.get("stream", False),
            openai_response=response,
        )

    def construct_nonchat_response(
        self,
        stream: bool,
        openai_response: Any,
    ) -> LLMResponse:
        """Construct an LLMResponse from an OpenAI response.

        Splits execution based on whether the `stream` parameter is set
        in the kwargs.
        """
        if stream:
            # If stream is defined and set to True,
            # openai returns a generator
            openai_response = cast(Iterator[Dict[str, Any]], openai_response)

            # Simply return the generator wrapped in an LLMResponse
            return LLMResponse(output="", stream_output=openai_response)

        # If stream is not defined or is set to False,
        # return default behavior
        openai_response = cast(Dict[str, Any], openai_response)
        if not openai_response.choices:
            raise ValueError("No choices returned from OpenAI")
        if openai_response.usage is None:
            raise ValueError("No token counts returned from OpenAI")
        trace_llm_call(
            output_messages=[
                {"role": "assistant", "content": openai_response.choices[0].text}
            ],
            token_count_completion=openai_response.usage.completion_tokens,
            token_count_prompt=openai_response.usage.prompt_tokens,
            token_count_total=openai_response.usage.total_tokens,
        )
        return LLMResponse(
            output=openai_response.choices[0].text,  # type: ignore
            prompt_token_count=openai_response.usage.prompt_tokens,  # type: ignore
            response_token_count=openai_response.usage.completion_tokens,  # noqa: E501 # type: ignore
        )

    def create_chat_completion(
        self, model: str, messages: List[Any], *args, **kwargs
    ) -> LLMResponse:
        trace_operation(
            input_mime_type="application/json",
            input_value={
                **kwargs,
                "model": model,
                "messages": messages,
                "args": args,
            },
        )
        function_calling_tools = [
            tool.get("function")
            for tool in kwargs.get("tools", [])
            if isinstance(tool, Dict) and tool.get("type") == "function"
        ]
        trace_llm_call(
            input_messages=messages,
            model_name=model,
            invocation_parameters={**kwargs, "model": model, "messages": messages},
            function_call=kwargs.get(
                "function_call", safe_get(function_calling_tools, 0)
            ),
        )
        response = self.client.chat.completions.create(
            model=model, messages=messages, *args, **kwargs
        )

        trace_operation(output_mime_type="application/json", output_value=response)

        return self.construct_chat_response(
            stream=kwargs.get("stream", False),
            openai_response=response,
        )

    def construct_chat_response(
        self,
        stream: bool,
        openai_response: Any,
    ) -> LLMResponse:
        """Construct an LLMResponse from an OpenAI response.

        Splits execution based on whether the `stream` parameter is set
        in the kwargs.
        """
        if stream:
            # If stream is defined and set to True,
            # openai returns a generator object
            openai_response = cast(Iterator[Dict[str, Any]], openai_response)

            # Simply return the generator wrapped in an LLMResponse
            return LLMResponse(output="", stream_output=openai_response)

        # If stream is not defined or is set to False,
        # extract string from response
        openai_response = cast(Dict[str, Any], openai_response)
        if not openai_response.choices:
            raise ValueError("No choices returned from OpenAI")
        if not openai_response.choices[0].message:
            raise ValueError("No message returned from OpenAI")
        if openai_response.usage is None:
            raise ValueError("No token counts returned from OpenAI")

        if openai_response.choices[0].message.content is not None:
            output = openai_response.choices[0].message.content
        else:
            try:
                output = openai_response.choices[0].message.function_call.arguments
            except AttributeError:
                try:
                    choice = openai_response.choices[0]
                    output = choice.message.tool_calls[-1].function.arguments
                except AttributeError as ae_tools:
                    raise ValueError(
                        "No message content or function"
                        " call arguments returned from OpenAI"
                    ) from ae_tools
        trace_llm_call(
            output_messages=[choice.message for choice in openai_response.choices],  # type: ignore
            token_count_completion=openai_response.usage.completion_tokens,
            token_count_prompt=openai_response.usage.prompt_tokens,
            token_count_total=openai_response.usage.total_tokens,
        )
        return LLMResponse(
            output=output,
            prompt_token_count=openai_response.usage.prompt_tokens,  # type: ignore
            response_token_count=openai_response.usage.completion_tokens,  # noqa: E501 # type: ignore
        )

import json
from guardrails_api_client import SimpleTypes
import jsonref
import regex
from typing import Any, Callable, Dict, List, Optional, Set, Tuple, Union, cast

from guardrails.actions.reask import NonParseableReAsk
from guardrails.classes.output_type import OutputTypes
from guardrails.classes.validation.validation_result import FailResult
from guardrails.schema.parser import get_all_paths
from guardrails.utils.safe_get import safe_get


### String to Dictionary Parsing ###
def has_code_block(
    string_value: str, code_type: str = ""
) -> Tuple[bool, Optional[int], Optional[int]]:
    """Checks if a string contains a code block denoted by leading and trailing
    tripple ticks (```) with an optional code type for the opening tag.

    Args::
        string_value (str): The string to check.
        code_type (str, optional): The specific code type to check for. Defaults to empty string.

    Returns
        bool: Whether or not the string contains the specified type of code block.
        int: The starting index of the code block.
        int: The ending index of the code block.
    """  # noqa
    block_border = "```"
    block_start_border = f"{block_border}{code_type}"

    block_start_index = string_value.find(block_start_border)
    if block_start_index != -1:
        block_end_index = string_value.find(
            block_border, (block_start_index + len(block_start_border))
        )
        return (
            (True, block_start_index, block_end_index)
            if block_end_index != -1
            else (False, None, None)
        )
    return (False, None, None)


def get_code_block(
    string_value: str, start: int, end: int, code_type: Optional[str] = ""
) -> str:
    """Takes a string, start and end indexes, and an optional code type to
    extract a code block from a string.

    Args::
        string_value (str): The string to extract a the code block from.
        start (int): The starting index of the code block.  This is assumed to be inclusive of the block boundaries.
        end (int): The ending index of the code block.  This is assumed to be inclusive of the block boundaries.
        code_type (str, optional): The specific code type to check for. Defaults to empty string.

    Returns:
        str: The contents of the code block.
    """  # noqa
    trimmed_input = string_value

    block_border = "```"
    block_start_border = f"{block_border}{code_type}"

    start_index = start + len(block_start_border)

    contents = trimmed_input[start_index:end]

    trimmed_output = contents.strip()

    return trimmed_output


def extract_json_from_ouput(
    output: str,
) -> Tuple[Optional[Union[Dict, List]], Optional[Exception]]:
    # try to load the whole output as json first
    # there can be corner cases with code blocks
    # and json/codeblocks inside json
    try:
        output_as_dict = json.loads(output, strict=False)
        return output_as_dict, None
    except json.decoder.JSONDecodeError:
        pass

    # Find and extract json from code blocks
    extracted_code_block = output
    has_json_block, json_start, json_end = has_code_block(output, "json")
    if has_json_block and json_start is not None and json_end is not None:
        extracted_code_block = get_code_block(output, json_start, json_end, "json")
    else:
        has_block, block_start, block_end = has_code_block(output)
        if has_block and block_start is not None and block_end is not None:
            extracted_code_block = get_code_block(output, block_start, block_end)
        else:
            json_pattern = regex.compile(r"\{(?:[^{}]+|\{(?:(?R)|[^{}]+)*\})*\}")
            json_groups = json_pattern.findall(output)
            json_start, json_end = output.find("{"), output.rfind("}")
            if len(json_groups) > 0 and len(json_groups[0]) == (
                json_end - json_start + 1
            ):
                extracted_code_block = json_groups[0]

    # Treat the output as a JSON string, and load it into a dict.
    error = None
    try:
        output_as_dict = json.loads(extracted_code_block, strict=False)
    except json.decoder.JSONDecodeError as e:
        output_as_dict = None
        error = e
    return output_as_dict, error


### Streaming Fragment Parsing ###
def is_valid_fragment(fragment: str, verified: set) -> bool:
    """Check if the fragment is a somewhat valid JSON."""

    # Strip fragment of whitespaces and newlines
    # to avoid duplicate checks
    text = fragment.strip(" \n")

    # Check if text is already verified
    if text in verified:
        return False

    # Check if text is valid JSON
    try:
        json.loads(text)
        verified.add(text)
        return True
    except ValueError as e:
        error_msg = str(e)
        # Check if error is due to missing comma
        if "Expecting ',' delimiter" in error_msg:
            verified.add(text)
            return True
        return False


def parse_fragment(fragment: str) -> Tuple[Union[str, List, Dict], Optional[str]]:
    """Parse the fragment into a dict."""

    # Complete the JSON fragment to handle missing brackets
    # Stack to keep track of opening brackets
    stack = []

    # Process each character in the string
    for char in fragment:
        if char in "{[":
            # Push opening brackets onto the stack
            stack.append(char)
        elif char in "}]":
            # Pop from stack if matching opening bracket is found
            if stack and (
                (char == "}" and stack[-1] == "{") or (char == "]" and stack[-1] == "[")
            ):
                stack.pop()

    # Add the necessary closing brackets in reverse order
    while stack:
        opening_bracket = stack.pop()
        if opening_bracket == "{":
            fragment += "}"
        elif opening_bracket == "[":
            fragment += "]"

    # Parse the fragment
    try:
        parsed_fragment: Union[Dict, List] = json.loads(fragment)
        return parsed_fragment, None
    except ValueError as e:
        return fragment, str(e)


### LLM Output Parsing ###
def parse_json_llm_output(
    output: str, **kwargs
) -> Tuple[
    Union[str, List, Dict, NonParseableReAsk, None],
    Union[Optional[Exception], str, bool, None],
]:
    if kwargs.get("stream", False):
        # Do expected behavior for StreamRunner
        # 1. Check if the fragment is valid JSON
        verified = kwargs.get("verified", set())
        fragment_is_valid = is_valid_fragment(output, verified)
        if not fragment_is_valid:
            return output, True

        # 2. Parse the fragment
        parsed_fragment, parsing_error = parse_fragment(output)
        return parsed_fragment, parsing_error

    # Else do expected behavior for Runner
    # Try to get json code block from output.
    # Return error and reask if it is not parseable.
    parsed_output, error = extract_json_from_ouput(output)

    if error:
        reask = NonParseableReAsk(
            incorrect_value=output,
            fail_results=[
                FailResult(
                    fix_value=None,
                    error_message="Output is not parseable as JSON",
                )
            ],
        )
        return reask, error
    return parsed_output, None


def parse_string_llm_output(output: str) -> Tuple[str, Optional[Exception]]:
    # Return a ValueError if the output is empty, else None
    error = ValueError("Empty response received.") if not output else None
    return output, error


def parse_llm_output(output: str, output_type: OutputTypes, **kwargs):
    if output_type == OutputTypes.STRING:
        return parse_string_llm_output(output)
    return parse_json_llm_output(output, **kwargs)


def prune_extra_keys(
    payload: Union[str, List[Any], Dict[str, Any]],
    schema: Dict[str, Any],
    *,
    json_path: str = "$",
    all_json_paths: Optional[Set[str]] = None,
) -> Union[str, List[Any], Dict[str, Any]]:
    if all_json_paths is None or not len(all_json_paths):
        all_json_paths = get_all_paths(schema)

    if isinstance(payload, dict):
        # Do full lookbehind
        wildcards: List[str] = [
            path.split(".*")[0] for path in all_json_paths if ".*" in path
        ]
        ancestor_is_wildcard = any(w in json_path for w in wildcards)
        actual_keys = list(payload.keys())
        for key in actual_keys:
            child_path = f"{json_path}.{key}"
            if child_path not in all_json_paths and not ancestor_is_wildcard:
                del payload[key]
            else:
                prune_extra_keys(
                    payload=payload.get(key),  # type: ignore
                    schema=schema,
                    json_path=child_path,
                    all_json_paths=all_json_paths,
                )
    elif isinstance(payload, list):
        for item in payload:
            prune_extra_keys(
                payload=item,
                schema=schema,
                json_path=json_path,
                all_json_paths=all_json_paths,
            )

    return payload


def coerce(value: Any, desired_type: Callable) -> Any:
    try:
        coerced_value = desired_type(value)
        return coerced_value
    except (ValueError, TypeError):
        return value


def try_json_parse(value: str) -> Any:
    try:
        return json.loads(value)
    except Exception:
        return value


def coerce_to_type(
    payload: Union[str, List[Any], Dict[str, Any], Any], schema_type: SimpleTypes
) -> Any:
    if schema_type == SimpleTypes.ARRAY:
        if isinstance(payload, str):
            payload = try_json_parse(payload)
        if not isinstance(payload, list):
            return coerce(payload, list)
        return payload
    elif schema_type == SimpleTypes.BOOLEAN:
        if not isinstance(payload, bool):
            return coerce(payload, bool)
        return payload
    elif schema_type == SimpleTypes.INTEGER:
        if not isinstance(payload, int):
            val = coerce(payload, int)
            return val
        return payload
    elif schema_type == SimpleTypes.NULL:
        return None
    elif schema_type == SimpleTypes.NUMBER:
        if not isinstance(payload, float):
            return coerce(payload, float)
        return payload
    elif schema_type == SimpleTypes.OBJECT:
        if isinstance(payload, str):
            payload = try_json_parse(payload)
        if not isinstance(payload, dict):
            return coerce(payload, dict)
        return payload
    elif schema_type == SimpleTypes.STRING:
        if not isinstance(payload, str) and not isinstance(payload, (list, dict)):
            return coerce(payload, str)
        return payload


def coerce_property(
    payload: Union[str, List[Any], Dict[str, Any], Any], schema: Dict[str, Any]
) -> Union[str, List[Any], Dict[str, Any]]:
    schema_type = schema.get("type")
    if schema_type:
        payload = coerce_to_type(payload, schema_type)

    ### Schema Composition ###
    one_of = schema.get("oneOf")
    if one_of:
        possible_values = []
        for sub_schema in one_of:
            possible_values.append(coerce_property(payload, sub_schema))
            payload = safe_get(list(filter(None, possible_values)), 0, payload)

    any_of = schema.get("anyOf")
    if any_of:
        possible_values = []
        for sub_schema in any_of:
            possible_values.append(coerce_property(payload, sub_schema))
            payload = safe_get(list(filter(None, possible_values)), 0, payload)

    all_of: List[Dict[str, Any]] = schema.get("allOf", [])
    if all_of:
        if_blocks = [sub for sub in all_of if sub.get("if")]
        if if_blocks:
            for if_block in if_blocks:
                factored_schema = {**schema, **if_block}
                factored_schema.pop("allOf", {})
                payload = coerce_property(payload, factored_schema)

            other_blocks = [sub for sub in all_of if not sub.get("if")]
            for sub_schema in other_blocks:
                payload = coerce_property(payload, sub_schema)

        else:
            factored_schema = {**schema}
            factored_schema.pop("allOf")
            for sub_schema in all_of:
                factored_schema = {**schema, **sub_schema}
            payload = coerce_property(payload, factored_schema)

    ### Object Schema ###
    properties: Dict[str, Any] = schema.get("properties", {})
    if properties and isinstance(payload, dict):
        for k, v in properties.items():
            payload_value = payload.get(k)
            if payload_value:
                payload[k] = coerce_property(payload_value, v)

    ### Object Additional Properties ###
    additional_properties_schema: Dict[str, Any] = schema.get(
        "additionalProperties", {}
    )
    if isinstance(additional_properties_schema, bool):
        additional_properties_schema = {}
    if additional_properties_schema and isinstance(payload, dict):
        declared_properties = properties.keys()
        additional_properties = [
            key for key in payload.keys() if key not in declared_properties
        ]
        for prop in additional_properties:
            payload_value = payload.get(prop)
            if payload_value:
                payload[prop] = coerce_property(
                    payload_value, additional_properties_schema
                )

    ### Conditional SubSchema ###
    if_block: Dict[str, Any] = schema.get("if", {})
    if if_block and isinstance(payload, dict):
        if_properties: Dict[str, Any] = if_block.get("properties", {})

        then_block: Dict[str, Any] = schema.get("then", {})
        then_properties: Dict[str, Any] = then_block.get("properties", {})

        else_block: Dict[str, Any] = schema.get("else", {})
        else_properties: Dict[str, Any] = else_block.get("properties", {})

        conditional_schema = else_properties

        condition_satisfied = True
        for k, v in if_properties.items():
            actual_value = safe_get(payload, k)
            condition_value = safe_get(v, "const")
            condition_satisfied = (
                condition_satisfied and actual_value == condition_value
            )

        if condition_satisfied:
            conditional_schema = then_properties

        factored_schema = {**schema, "properties": {**properties, **conditional_schema}}
        factored_schema.pop("if", {})
        factored_schema.pop("then", {})
        factored_schema.pop("else", {})
        payload = coerce_property(payload, factored_schema)

    ### Array Schema ###
    item_schema: Dict[str, Any] = schema.get("items", {})
    if isinstance(payload, list) and item_schema:
        coerced_items = []
        for item in payload:
            coerced_items.append(coerce_property(item, item_schema))
        payload = coerced_items

    return payload


def coerce_types(
    payload: Union[str, List[Any], Dict[str, Any], Any], schema: Dict[str, Any]
) -> Union[str, List[Any], Dict[str, Any]]:
    dereferenced_schema = cast(
        Dict[str, Any], jsonref.replace_refs(schema)
    )  # for pyright
    return coerce_property(payload, dereferenced_schema)

import json
import re
from typing import Any, Dict, Union

from guardrails.classes.output_type import OutputTypes

from guardrails.types.validator import ValidatorMap
from guardrails.prompt.prompt import Prompt
from guardrails.prompt.instructions import Instructions
from guardrails.types.inputs import MessageHistory


def prompt_uses_xml(prompt: str) -> bool:
    xml_const_regx = re.compile(r"gr\..*xml_.*")
    contains_xml_const = xml_const_regx.search(prompt) is not None
    contains_xml_output = "xml_output_schema" in prompt
    return contains_xml_output or contains_xml_const


def prompt_content_for_string_schema(
    output_schema: Dict[str, Any], validator_map: ValidatorMap, json_path: str
) -> str:
    # NOTE: Is this actually necessary?
    # We should check how LLMs perform this this vs just sending the JSON Schema
    prompt_content = ""
    description = output_schema.get("description")
    if description:
        prompt_content += (
            f"Here's a description of what I want you to generate: {description}"
        )
    validators = validator_map.get(json_path, [])
    if len(validators):
        prompt_content += (
            "\n\nYour generated response should satisfy the following properties:"
        )
        for validator in validators:
            prompt_content += f"\n- {validator.to_prompt()}"

    prompt_content += "\n\nDon't talk; just go."
    return prompt_content


# Supersedes Schema.transpile
def prompt_content_for_schema(
    output_type: OutputTypes,
    output_schema: Dict[str, Any],
    validator_map: ValidatorMap,
    json_path: str = "$",
) -> str:
    if output_type == OutputTypes.STRING:
        return prompt_content_for_string_schema(output_schema, validator_map, json_path)
    return json.dumps(output_schema)


def messages_to_prompt_string(
    messages: Union[list[dict[str, Union[str, Prompt, Instructions]]], MessageHistory],
) -> str:
    messages_copy = ""
    for msg in messages:
        content = (
            msg["content"].source  # type: ignore
            if isinstance(msg["content"], Prompt)
            or isinstance(msg["content"], Instructions)  # type: ignore
            else msg["content"]  # type: ignore
        )
        messages_copy += content
    return messages_copy

from typing import Any, Dict, List, Optional, Tuple, Union
from guardrails.logger import logger


def safe_get_with_brackets(
    container: Union[str, List[Any], Any], key: Any, default: Optional[Any] = None
) -> Any:
    try:
        value = container[key]
        if not value:
            return default
        return value
    except Exception as e:
        logger.debug(
            f"""
            Failed to get value for key: {key} out of container: {container}.
            Reason: {e}
            Fallbacking to default value...
            """
        )
        return default


def safe_get(
    container: Union[str, List[Any], Dict[Any, Any], Tuple],
    key: Any,
    default: Optional[Any] = None,
) -> Any:
    if isinstance(container, dict):
        return container.get(key, default)
    else:
        return safe_get_with_brackets(container, key, default)

from datetime import datetime
import json
from typing import Any, Optional
import warnings
from dataclasses import asdict, is_dataclass
from pydantic import BaseModel

from guardrails.classes.generic.default_json_encoder import DefaultJSONEncoder


# This is the same logic as the DefaultJSONEncoder but without stringifying everything
def to_dict(o):
    if hasattr(o, "to_dict"):
        return o.to_dict()
    elif isinstance(o, BaseModel):
        return o.model_dump()
    elif is_dataclass(o):
        return asdict(o)
    elif isinstance(o, set):
        return list(o)
    elif isinstance(o, datetime):
        return o.isoformat()
    elif hasattr(o, "__dict__"):
        return o.__dict__
    return o


# TODO: What other common cases we should consider?
def serialize(val: Any) -> Optional[str]:
    try:
        return json.dumps(val, cls=DefaultJSONEncoder)
    except Exception as e:
        warnings.warn(str(e))
        return None


# We want to do the oppisite of what we did in the DefaultJSONEncoder
# TODO: What's a good way to expose a configurable API for this?
#       Do we wrap JSONDecoder with an extra layer to supply the original object?
def deserialize(original: Optional[Any], serialized: Optional[str]) -> Any:
    try:
        if original is None or serialized is None:
            return None

        loaded_val = json.loads(serialized)
        if isinstance(original, datetime):
            return datetime.fromisoformat(loaded_val)
        elif isinstance(original, set):
            return set(original)
        elif hasattr(original, "__class__"):
            # TODO: Handle nested classes
            # NOTE: nested pydantic classes already work
            if isinstance(loaded_val, dict):
                return original.__class__(**loaded_val)
            elif isinstance(loaded_val, list):
                return original.__class__(loaded_val)
        return loaded_val
    except Exception as e:
        warnings.warn(str(e))
        return None

from abc import ABC, abstractmethod
from pathlib import Path
from typing import List, Optional

try:
    import sqlalchemy
    from sqlalchemy import text

    _HAS_SQLALCHEMY = True
except ImportError:
    _HAS_SQLALCHEMY = False


class SQLDriver(ABC):
    """Abstract class for SQL drivers.

    The expose common functionality for validating SQL queries.
    """

    @abstractmethod
    def validate_sql(self, query: str) -> List[str]: ...

    @abstractmethod
    def get_schema(self) -> str: ...


class SimpleSqlDriver(SQLDriver):
    """Simple SQL driver which uses sqlvalidator to validate SQL queries.

    Does not understands dialects and is not connected to a database.
    """

    def validate_sql(self, query: str) -> List[str]:
        import sqlvalidator

        sql_query = sqlvalidator.parse(query)
        if not sql_query.is_valid():
            return sql_query.errors
        return sql_query.errors

    def get_schema(self) -> str:
        raise NotImplementedError


class SqlAlchemyDriver(SQLDriver):
    """SQL driver which uses sqlalchemy to validate SQL queries.

    It can setup the database schema and check if the queries are valid
    by connecting to the database.
    """

    def __init__(self, schema_file: Optional[str], conn: Optional[str]) -> None:
        if not _HAS_SQLALCHEMY:
            raise ImportError(
                """The functionality requires sqlalchemy to be installed.
                              Please install it using `poetry add SqlAlchemy`"""
            )

        if schema_file is not None and conn is None:
            raise RuntimeError(
                """schema_file should accompany a sql connection string for
           guardrails to apply it to a database backend.
           Use sqlite for ex: sqlite://"""
            )

        if conn is not None:
            try:
                self._engine = sqlalchemy.create_engine(conn)
                self._conn = self._engine.connect()
            except Exception as ex:
                raise ValueError(ex)

        if schema_file is not None:
            schema = Path(schema_file).read_text()
            if conn is not None and conn.startswith("sqlite"):
                self._conn.connection.executescript(schema)  # type: ignore
            else:
                from sqlalchemy import text

                self._conn.execute(text(schema))

    def validate_sql(self, query: str) -> List[str]:
        exceptions: List[str] = []
        try:
            self._conn.execute(text(query))
        except Exception as ex:
            exceptions.append(str(ex))
        return exceptions

    def get_schema(self) -> str:
        # Get table schema using sqlalchemy.inspect
        insp = sqlalchemy.inspect(self._conn)

        schema = {}
        for table in insp.get_table_names():
            schema[table] = {}
            for column in insp.get_columns(table):
                schema[table][column["name"]] = {"type": column["type"]}

            # Get foreign keys
            for fk in insp.get_foreign_keys(table):
                schema[table][fk["constrained_columns"][0]]["foreign_key"] = {
                    "table": fk["referred_table"],
                    "column": fk["referred_columns"][0],
                }

        # Create a nicely formatted schema from the dictionary
        formatted_schema = []
        for table, columns in schema.items():
            formatted_schema.append(f"Table: {table}")
            for column, column_info in columns.items():
                formatted_schema.append(f"    Column: {column}")
                for info, value in column_info.items():
                    formatted_schema.append(f"        {info}: {value}")

        return "\n".join(formatted_schema)


def create_sql_driver(
    schema_file: Optional[str] = None, conn: Optional[str] = None
) -> SQLDriver:
    if schema_file is None and conn is None:
        return SimpleSqlDriver()
    return SqlAlchemyDriver(schema_file=schema_file, conn=conn)

from typing import Dict, List, Optional
from guardrails.logger import logger
from guardrails.types.pydantic import ModelOrListOfModels


# takes processed schema and converts it to a openai tool object
def schema_to_tool(schema: Dict) -> dict:
    tool = {
        "type": "function",
        "function": {
            "name": "gd_response_tool",
            "description": "A tool for generating responses to guardrails."
            " It must be called last in every response.",
            "parameters": schema,
            "required": schema.get("required") or [],
        },
    }
    return tool


def set_additional_properties_false_iteratively(schema):
    stack = [schema]
    while stack:
        current = stack.pop()
        if isinstance(current, dict):
            if "properties" in current:
                current["required"] = list(
                    current["properties"].keys()
                )  # this has to be set
            if "maximum" in current:
                logger.warn("Property maximum is not supported. Dropping")
                current.pop("maximum")  # the api does not like these set
            if "minimum" in current:
                logger.warn("Property maximum is not supported. Dropping")
                current.pop("minimum")  # the api does not like these set
            if "default" in current:
                logger.warn("Property default is not supported. Marking field Required")
                current.pop("default")  # the api does not like these set
            for prop in current.values():
                stack.append(prop)
        elif isinstance(current, list):
            for prop in current:
                stack.append(prop)
        if (
            isinstance(current, dict)
            and "additionalProperties" not in current
            and "type" in current
            and current["type"] == "object"
        ):
            current["additionalProperties"] = False  # the api needs these set


def json_function_calling_tool(
    schema: Dict,
    tools: Optional[List] = None,
) -> List:
    tools = tools or []
    tools.append(schema_to_tool(schema))  # type: ignore
    return tools


def output_format_json_schema(schema: ModelOrListOfModels) -> dict:
    parsed_schema = schema.model_json_schema()  # type: ignore

    set_additional_properties_false_iteratively(parsed_schema)

    return {
        "type": "json_schema",
        "json_schema": {
            "name": parsed_schema["title"],
            "schema": parsed_schema,
            "strict": True,
        },  # type: ignore
    }

